actual_early_constants:
// EARLIEST path constants for the Electron main process.
//
// CONSTRAINTS:
//   - No business-module dependencies (no @shared / @main / business code).
//   - Only node built-ins and `electron` are allowed.
//   - Electron's `app.getPath()` is safe at this layer: it works at module
//     import time, before `app.whenReady()`. Verified by LoggerService which
//     constructs at module load and consumes LOGS_DIR through this file.
//
// CONSUMERS (all main-process bootstrap services):
//   - src/main/core/logger/LoggerService.ts          → uses LOGS_DIR
//   - src/main/data/bootConfig/BootConfigService.ts  → uses BOOT_CONFIG_PATH
//   - src/main/core/paths/pathRegistry.ts            → re-exposes LOGS_DIR as 'app.logs'
//   - src/main/core/preboot/userDataLocation.ts      → uses resolveDevUserDataPath

import os from 'node:os'
import path from 'node:path'

import { app } from 'electron'

// Duplicated from HOME_DIRNAME in @shared/utils/branding: this layer loads
// before app.whenReady() and may not import business modules (see CONSTRAINTS
// above). Change both together.
export const CHERRY_HOME_DIRNAME = '.the-boss'
export const CHERRY_HOME = path.join(os.homedir(), CHERRY_HOME_DIRNAME)
export const BOOT_CONFIG_PATH = path.join(CHERRY_HOME, 'boot-config.json')

const DEFAULT_DEV_USER_DATA_SUFFIX = 'Dev'

// The suffix is concatenated into directory names, so it must stay a single
// path component: separators, drive colons, and control/Windows-forbidden
// characters could normalize the dev directories back onto the packaged ones
// (e.g. `/../CherryStudio`). Trailing dots are rejected separately — Windows
// strips them, aliasing `CherryStudio.` (from suffix `.`) onto the packaged
// `CherryStudio` directory. Anything a filesystem accepts inside a single
// component — spaces, non-ASCII — stays valid.
const FORBIDDEN_DEV_USER_DATA_SUFFIX = /[\\/:*?"<>|]|\p{Cc}/u

/**
 * Dev-instance directory suffix (`CherryStudio` → `CherryStudioDev`),
 * overridable via CS_DEV_USER_DATA_SUFFIX.
 *
 * Blank values fall back to the default; a value that is not a single path
 * component aborts startup instead, because falling back would silently merge
 * a profile meant to be isolated into the shared `Dev` one. Throwing is also
 * the only way to report this: @logger is unavailable here, since
 * LoggerService consumes LOGS_DIR from this file.
 */
function resolveDevUserDataSuffix(): string {
  const configured = process.env.CS_DEV_USER_DATA_SUFFIX?.trim()
  if (!configured) return DEFAULT_DEV_USER_DATA_SUFFIX
  if (FORBIDDEN_DEV_USER_DATA_SUFFIX.test(configured) || configured.endsWith('.')) {
    throw new Error(
      `CS_DEV_USER_DATA_SUFFIX ${JSON.stringify(configured)} must be a single path component ` +
        '(no path separator, drive colon, Windows-reserved character or trailing dot).'
    )
  }
  return configured
}

/**
 * Dev-instance userData directory (`…/CherryStudio` → `…/CherryStudioDev`).
 * Applied by `core/preboot/userDataLocation.ts` and — on Windows and Linux,
 * where logs live inside userData — by the logs diversion below, so both
 * derive from one definition.
 */
export function resolveDevUserDataPath(): string {
  return app.getPath('userData') + resolveDevUserDataSuffix()
}

// Divert dev logs BEFORE the app.getPath('logs') call below caches Electron's
// default. That default never sees the dev userData suffix — on macOS it
// derives from the app *name* (~/Library/Logs/CherryStudio), elsewhere from
// the not-yet-suffixed userData — so without this a dev run would interleave
// its logs with a packaged install's.
if (!app.isPackaged) {
  app.setAppLogsPath(
    process.platform === 'darwin'
      ? app.getPath('logs') + resolveDevUserDataSuffix()
      : path.join(resolveDevUserDataPath(), 'logs')
  )
}

/**
 * Logs directory. Resolves to Electron's platform-standard location:
 *   - macOS:   ~/Library/Logs/<App>/
 *   - Windows: %APPDATA%/<App>/logs
 *   - Linux:   ~/.config/<App>/logs
 * where `<App>` carries the dev suffix in unpackaged runs (see above).
 *
 * Single source of truth — referenced by LoggerService directly and exposed
 * via pathRegistry as the `app.logs` key for `application.getPath()` consumers.
 */
export const LOGS_DIR = app.getPath('logs')

actual_user_data_selection:
import fs from 'node:fs'
import path from 'node:path'

import { app } from 'electron'

import { loggerService } from '@logger'
import { resolveDevUserDataPath } from '@main/core/paths/constants'
import { isLinux, isPortable, isWin } from '@main/core/platform'
import { bootConfigService } from '@main/data/bootConfig'
import { PRODUCT_DIRNAME } from '@shared/utils/branding'

const logger = loggerService.withContext('Preboot')

/** Upstream's userData directory name, detected only to report it, never adopted. */
const LEGACY_UPSTREAM_DIRNAME = 'CherryStudio'

/**
 * "userData" in this module means Electron's complete OS-level userData
 * directory, including user content, Chromium state, and — on Windows and
 * Linux — application logs (macOS keeps logs in ~/Library/Logs instead).
 */

export function getNormalizedExecutablePath(): string {
  if (isLinux && process.env.APPIMAGE) {
    return path.join(path.dirname(process.env.APPIMAGE), 'cherry-studio.appimage')
  }
  if (isWin && isPortable) {
    return path.join(process.env.PORTABLE_EXECUTABLE_DIR || '', 'cherry-studio-portable.exe')
  }
  return app.getPath('exe')
}

export function canonicalizeUserDataPath(userDataPath: string): string {
  if (!path.isAbsolute(userDataPath)) {
    throw new Error(`userData path must be absolute: ${userDataPath}`)
  }
  return path.normalize(userDataPath)
}

/**
 * Resolve Electron's userData directory before the path registry is frozen.
 * Pending relocation is deliberately not executed here: after the source path
 * is resolved and its single-instance lock is acquired, the
 * `services/userDataRelocation` domain owns validation, copy/switch, commit,
 * progress UI, and relaunch (`runUserDataRelocation()` called from main.ts).
 * The `app.user_data_path` mapping read below is written by that domain's
 * commit step.
 *
 * Electron derives sessionData lazily from userData when no explicit
 * sessionData path was set. Keeping this setPath call before app.whenReady()
 * therefore carries Cookies, Local Storage, IndexedDB, and other Chromium
 * storage to the selected directory as well.
 */
export function resolveUserDataLocation(): void {
  if (!app.isPackaged) {
    const devPath = resolveDevUserDataPath()
    app.setPath('userData', devPath)
    logger.info('userData set with dev suffix', { devPath })
    return
  }

  const exe = getNormalizedExecutablePath()
  const resolved = bootConfigService.get('app.user_data_path')?.[exe]
  if (resolved && isUsableDataDir(resolved)) {
    app.setPath('userData', resolved)
    logger.info('userData set from BootConfig', { exe, resolved })
    return
  }

  if (isPortable) {
    const portableDir = process.env.PORTABLE_EXECUTABLE_DIR
    const portablePath = path.join(portableDir || app.getPath('exe'), 'data')
    app.setPath('userData', portablePath)
    logger.info('userData set for portable build', { portablePath })
    return
  }

  const brandedPath = path.join(app.getPath('appData'), PRODUCT_DIRNAME)
  app.setPath('userData', brandedPath)
  logger.info('userData set from branding', { brandedPath })
  warnOnUnadoptedLegacyDataDir(brandedPath)
}

/**
 * This fork deliberately starts with an empty profile rather than adopting an
 * upstream Cherry Studio one: the directory layouts are only coincidentally
 * compatible, and silently importing another app's data is worse than starting
 * clean. Log it so an operator can find the old directory instead of concluding
 * their data vanished.
 */
function warnOnUnadoptedLegacyDataDir(brandedPath: string): void {
  const legacyPath = path.join(app.getPath('appData'), LEGACY_UPSTREAM_DIRNAME)
  if (legacyPath === brandedPath || !isUsableDataDir(legacyPath)) return

  logger.warn('Legacy Cherry Studio data directory found and deliberately not adopted', {
    legacyPath,
    brandedPath
  })
}

/**
 * A usable data directory must be readable, writable, and searchable. This is
 * shared with v1-to-v2 migration path selection so both startup paths enforce
 * the same filesystem bar.
 */
export function isUsableDataDir(value: string): boolean {
  try {
    if (!fs.statSync(value).isDirectory()) return false
    fs.accessSync(value, fs.constants.R_OK | fs.constants.W_OK | fs.constants.X_OK)
    return true
  } catch {
    return false
  }
}

actual_main_entry:
/**
 * Electron main-process entry — preboot → bootstrap → running.
 *
 * DO NOT add new code here. If you feel the need to, you almost certainly
 * misunderstand the startup timing or service architecture. New services
 * belong in the lifecycle system (see core/lifecycle/); non-removable
 * preboot steps belong in core/preboot/; removable capabilities that must
 * execute at preboot time belong in their nature-home (e.g. services/)
 * and are invoked from here. This file is glue — it should only shrink.
 */

// BootConfig must load before any other import (configures userData path)

import '@main/data/bootConfig'
import { application } from '@application'
import { serviceList } from '@main/core/application/serviceRegistry'
// Preboot phase — order matters. See core/preboot/README.md.
import { runBackupRestoreGate } from '@main/core/preboot/backupRestoreGate'
import { configureChromiumFlags } from '@main/core/preboot/chromiumFlags'
import { initCrashTelemetry } from '@main/core/preboot/crashTelemetry'
import { requireSingleInstance } from '@main/core/preboot/singleInstance'
import { resolveUserDataLocation } from '@main/core/preboot/userDataLocation'
import { runV2MigrationGate } from '@main/core/preboot/v2MigrationGate'
import { MINI_APP_SCHEME_DECLARATION } from '@main/features/miniApp/runtime/protocol'
import { runDataReset } from '@main/services/dataReset'
import { CHERRY_MEDIA_SCHEME_DECLARATION } from '@main/services/mediaProtocol'
import { initSentry } from '@main/services/sentry'
import { runUserDataRelocation } from '@main/services/userDataRelocation'
import { removeCommandPath } from '@main/services/prometheus/commandPath'
import { getApplicationId } from '@main/utils/appEdition'

// should be the first to resolveUserDataLocation()
resolveUserDataLocation()
requireSingleInstance()
configureChromiumFlags()
initCrashTelemetry()
initSentry()
// Privileged schemes must be declared before the app is ready, and only ONCE per
// process — startApp() itself awaits app.whenReady(), so this cannot move in there.
protocol.registerSchemesAsPrivileged([CHERRY_MEDIA_SCHEME_DECLARATION, MINI_APP_SCHEME_DECLARATION])
// Freeze the path registry — bootstrap() asserts this completed.
application.initPathRegistry()

import { electronApp } from '@electron-toolkit/utils'
import { app, protocol } from 'electron'

import { loggerService } from '@logger'

import { registerIpc } from './ipc'
import { versionService } from './services/VersionService'

const logger = loggerService.withContext('MainEntry')

const startApp = async () => {
  if (process.argv.includes('--remove-managed-path')) {
    await removeCommandPath()
    app.exit(0)
    return
  }
  // Reset before backup, migration, or services open user data.
  runDataReset()

  // userData relocation: a pending/failed relocation makes this a dedicated
  // relocation launch (execute or explain, then relaunch) before any service
  // opens files under the source tree. See services/userDataRelocation/README.md.
  const relocationResult = await runUserDataRelocation()
  if (relocationResult === 'handled') return

  // Backup-restore gate: swap in a staged restored DB (if any) before the v2
  // migration gate reads the DB. Never throws; on any failure the old DB
  // stays live and the app starts normally.
  await runBackupRestoreGate()

  // 'handled' = migration window took over OR fatal error already quit the app.
  const migrationResult = await runV2MigrationGate()
  if (migrationResult === 'handled') return

  // Set the Windows AppUserModelID — the identity Windows uses to attribute this
  // app's notifications, taskbar icon grouping, and Jump Lists (no-op on macOS/Linux).
  // Must run before any window is created or notification fires, hence after the
  // migration gate returns and before lifecycle bootstrap.
  electronApp.setAppUserModelId(getApplicationId())

  // Start lifecycle (BeforeReady runs parallel with app.whenReady)
  application.registerAll(serviceList)
  const bootstrapPromise = application.bootstrap()

  await app.whenReady()
  // Wait for lifecycle bootstrap (all core services are now ready)
  await bootstrapPromise

  // Record current version for upgrade-path tracking
  versionService.recordCurrentVersion()

  // Legacy monolithic IPC registration — causes timing coupling between
  // bootstrap and IPC readiness. TODO(v2): decompose into per-service
  // ipcHandle/ipcOn inside lifecycle services.
  await registerIpc()
}

// Top-level safety net: bootstrap() handles known fatal errors internally
// (ServiceInitError → dialog → exit/relaunch), so this catch only fires
// for unexpected errors that escape the normal handling path.
startApp().catch((error) => {
  logger.error('Fatal startup error:', error)
  application.forceExit(1)
})

actual_harness_gate_contract:
// Complete HARNESS acceptance orchestration. Requires already built binaries;
// never builds, installs, starts a daemon, uses D0, or treats a skip as success.
// Usage: node bauar-harness-gate.mjs <api-host-test-bin> <kernel-test-bin> <uar-bin> <uar-source>
import assert from 'node:assert/strict';
import { createHash, randomUUID } from 'node:crypto';
import { mkdtemp, mkdir, readFile, writeFile, rename, rm, access } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { once } from 'node:events';
import { isDeepStrictEqual } from 'node:util';
import { startPeer, startFaultProxy } from './bauar-harness-peer.mjs';
import { nativeCompatibilityGate } from './bauar-harness-native.mjs';
import { emitKernelStage } from './bauar-harness-kernel-stage.mjs';
import { providerFixture, secret, until, expected, request, launch, alive, stop, childStatus, instanceId } from './bauar-harness-runtime.mjs';

const [hostBinary, kernelBinary, uarBinary, uarSource] = process.argv.slice(2).map(value => resolve(value));
assert.ok(hostBinary && kernelBinary && uarBinary && uarSource, 'Four explicit binary/source paths required');
for (const binary of [hostBinary, kernelBinary, uarBinary]) await access(binary);
assert.equal(process.versions.node.split('.')[0], '24', 'Use the accepted Node 24 runtime');
const root = await mkdtemp(join(tmpdir(), 'bauar-harness-'));
const owner = secret(), other = secret(), master = secret(), modelCredential = secret();
const mcpCredential = `Bearer ${secret()}`;
const completed = [];
let peer, proxy, provider, host, kernelChild, base, selection;
let stage = 'setup', cancellationSurface = null, cancellationStep = null;
const hostRoot = join(root, 'boss');
const configPath = join(hostRoot, 'config.json');
const hash = value => `$sha256$${createHash('sha256').update(value).digest('hex')}`;
const auth = { token: owner };
const view = body => body.delegation ?? body;
const endpoint = task => `/api/uar/delegations/${task}`;
const admissions = () => proxy.observations.filter(item => item.method === 'POST' && item.path.endsWith('/full-harness/v1/tasks')).length;
const effects = label => peer.effects.filter(item => item === label).length;
function passed(name) {
  assert.ok(!completed.includes(name)); completed.push(name);
  // Names are the fixed scenario literals below, never request/provider data.
  console.error(JSON.stringify({ harnessCompletedCase: name, completedCaseCount: completed.length }));
}

async function hostStart() {
  await rm(join(hostRoot, 'ready.json'), { force: true });
  await rm(join(hostRoot, 'stop'), { force: true });
  host = launch(hostBinary, ['--exact', 'bauar_private_host', '--nocapture'], hostRoot, {
    // Direct libtest launch must retain .cargo/config.toml's debug agent-loop
    // stack floor; privateEnv intentionally drops the parent environment.
    RUST_MIN_STACK: '16777216',
    BAUAR_HOST_ROOT: hostRoot, BAUAR_HOST_CONFIG: configPath,
    BAUAR_UAR_BEARER: provider.token, BAUAR_MODEL_KEY: modelCredential,
  }, { classifyStderr: true });
  const ready = await until('real private BossFang router', async () => {
    alive(host);
    try { return JSON.parse(await readFile(join(hostRoot, 'ready.json'), 'utf8')); }
    catch { return false; }
  });
  assert.equal(ready.router, 'production');
  assert.equal(ready.backgroundSweep, false);
  base = ready.base;
}
async function hostCommand(operation) {
  const id = randomUUID(), commands = join(hostRoot, 'commands');
  const temporary = join(commands, `${id}.tmp`);
  await writeFile(temporary, JSON.stringify(operation), { mode: 0o600 });
  await rename(temporary, join(commands, `${id}.request`));
  return until('real private storage checkpoint', async () => {
    alive(host);
    try { return JSON.parse(await readFile(join(commands, `${id}.response`), 'utf8')); }
    catch { return false; }
  });
}
async function job(label, agent) {
  const row = await expected(base, '/api/tasks', { ...auth, method: 'POST',
    body: { title: label, description: 'Perform the bound safe fixture effect once.', assigned_to: agent } }, [201]);
  assert.ok(row.id);
  return row.id;
}
async function admit(jobId, streaming = false, override = {}) {
  try {
    return view(await expected(base, `/api/uar/jobs/${jobId}/admission`, {
      ...auth, method: 'POST', body: { ...selection, streaming, ...override } }, [202]));
  } catch (error) {
    // Preserve the first refusal; reading the private snapshot does not retry it.
    if (error instanceof assert.AssertionError) {
      const binding = await hostCommand({ operation: 'read_binding_status' });
      console.error(JSON.stringify({ bindingCheckpoint: binding }));
    }
    throw error;
  }
}
async function current(task) { return view(await expected(base, endpoint(task), auth, [200, 202])); }
async function approval(task) {
  let after = 0;
  return until('actual provider exact approval event', async () => {
    const observed = await expected(base, `${endpoint(task)}/events?after=${after}`, auth);
    const event = observed.events.find(item => item.parts?.some(part => part.type === 'approval_required'));
    for (const item of observed.events) after = Math.max(after, item.eventId);
    if (event) {
      const part = event.parts.find(part => part.type === 'approval_required');
      assert.ok(part.approval_id);
      return { id: part.approval_id, cursor: event.eventId, projection: observed.delegation };
    }
    assert.ok(!observed.delegation.terminalAt, 'Provider ended before required approval');
    return false;
  });
}
async function decide(task, id, approved, statuses = [200], revision) {
  const snapshot = await current(task);
  return view(await expected(base, `${endpoint(task)}/approve`, { ...auth, method: 'POST',
    body: { approvalId: id, expectedRevision: revision ?? snapshot.revision, approved } }, statuses));
}
async function terminal(task, expectedState) {
  return until('actual terminal provider outcome', async () => {
    const observed = await expected(base, `${endpoint(task)}/events?after=0`, auth);
    const projection = observed.delegation;
    if (!projection.terminalAt) return false;
    assert.equal(projection.executionState, expectedState);
    const receipt = await expected(provider.base,
      `/api/uar/full-harness/v1/tasks/${projection.uarTaskId}`, provider.auth);
    assert.ok(receipt.task_id === projection.uarTaskId && receipt.run_id === projection.uarRunId
      && receipt.runtime_epoch === projection.runtimeEpoch, 'Terminal receipt must retain original correlation');
    assert.ok(receipt.terminal_at && Number.isSafeInteger(receipt.cursor), 'Actual terminal provider cursor required');
    if (projection.cursor < receipt.cursor) return false;
    assert.equal(projection.cursor, receipt.cursor, 'All original terminal events must be applied');
    return projection;
  });
}
async function board(jobId) { return expected(base, `/api/tasks/${jobId}`, auth); }
async function privateA2a(task) {
  const result = await expected(base, '/a2a', { ...auth, method: 'POST',
    body: { jsonrpc: '2.0', id: 'bauar-get', method: 'tasks/get', params: { id: task } } });
  assert.ok(result.result && !result.error, 'Actual private A2A task must be available to its owner');
  return result.result;
}

try {
  peer = await startPeer({ effectFile: join(root, 'effects.jsonl'), mcpCredential, modelCredential });
  proxy = await startFaultProxy();
  provider = await providerFixture({ root, binary: uarBinary, source: uarSource, peer, proxy, mcpCredential, modelCredential });
  await provider.start();
  selection = await provider.seed();
  await mkdir(hostRoot, { recursive: true });
  const config = { home_dir: join(hostRoot, 'home'), data_dir: join(hostRoot, 'data'), api_key: hash(master),
    task_board: { assignee_wake: false },
    users: [{ name: 'bauar-owner', role: 'owner', api_key_hash: hash(owner) },
      { name: 'bauar-other', role: 'owner', api_key_hash: hash(other) }],
    default_model: { provider: 'openai', model: 'gpt-5.4-mini', api_key_env: 'BAUAR_MODEL_KEY', base_url: `${peer.base}/v1` },
    uar: { enabled: true, selected_instance_id: instanceId, instances: [{ id: instanceId, ownership: 'external',
      endpoints: provider.endpoints, workspace_locality: 'local', profile: 'uar.service-instance/1',
      credential_ref: 'env://BAUAR_UAR_BEARER', required_capabilities: ['full_harness_delegation_v1'] }] } };
  await writeFile(configPath, JSON.stringify(config), { mode: 0o600 });
  await hostStart();
  const manifest = `name = "bauar-assignee"\nmodule = "builtin:chat"\n[model]\nprovider = "openai"\nmodel = "gpt-5.4-mini"\napi_key_env = "BAUAR_MODEL_KEY"\nbase_url = ${JSON.stringify(`${peer.base}/v1`)}\nsystem_prompt = "Execute the fixture request."\n`;
  const agent = (await expected(base, '/api/agents', { ...auth, method: 'POST', body: { manifest_toml: manifest } }, [201])).agent_id;
  assert.ok(agent, 'Actual stored assigned agent required');
  const unauthJob = await job('BAUAR_AUTH', agent);
  for (const token of [undefined, master]) {
    await expected(base, `/api/uar/jobs/${unauthJob}/admission`, { token, method: 'POST', body: selection }, [401, 403]);
  }
  for (const requirement of [{ requiresSteer: true }, { requiresDurableRestartRecovery: true },
    { authority: 'delegated_user' }, { configurationPolicy: 'native_agent' }]) {
    await expected(base, `/api/uar/jobs/${unauthJob}/admission`, { ...auth, method: 'POST', body: { ...selection, ...requirement } }, [422]);
  }
  assert.equal(admissions(), 0);
  await expected(base, `/api/tasks/${unauthJob}`, { ...auth, method: 'DELETE' }, [204]);
  passed('registered-owner-and-explicit-unsupported');

  for (const streaming of [false, true]) {
    stage = streaming ? 'streaming_selected' : 'normal_selected';
    const label = streaming ? 'BAUAR_STREAM' : 'BAUAR_NORMAL';
    const id = await job(label, agent), before = admissions();
    const run = await admit(id, streaming), task = run.bossTaskId;
    if (!(task && run.uarTaskId && run.uarRunId)) {
      const known = (value, allowed) => allowed.includes(value) ? value : null;
      const present = value => typeof value === 'string' && value.length > 0;
      console.error(JSON.stringify({ admissionCheckpoint: {
        bossTaskIdPresent: present(task), uarTaskIdPresent: present(run.uarTaskId),
        uarRunIdPresent: present(run.uarRunId), runtimeEpochPresent: present(run.runtimeEpoch),
        admissionState: known(run.admissionState, ['pending', 'admitted', 'refused', 'unresolved']),
        executionState: known(run.executionState, ['pending', 'submitted', 'reserved', 'running', 'completed', 'failed', 'cancelled', 'rejected']),
        recoveryState: known(run.recoveryState, ['available', 'outcome_unknown', 'recovery_unsupported', 'expired']),
        diagnostics: (run.remoteDiagnostics ?? []).map(item => known(item.code,
          ['uar_runtime_epoch_lost', 'uar_attempt_outcome_unknown', 'uar_retention_expired'])),
        providerAdmissionStatuses: proxy.observations.filter(item => item.method === 'POST'
          && item.path.endsWith('/full-harness/v1/tasks')).map(item => item.status ?? null),
        providerAdmissionRefusalCodes: proxy.observations.filter(item => item.method === 'POST'
          && item.path.endsWith('/full-harness/v1/tasks')).map(item => item.refusalCode ?? null),
      } }));
    }
    assert.ok(task && run.uarTaskId && run.uarRunId);
    const pending = await approval(task);
    assert.equal(effects(label), 0, 'No effect before exact approval');
    const beforeRefusal = await current(task), revision = beforeRefusal.revision;
    await decide(task, 'wrong-exact-id', true, [409], revision);
    assert.ok(isDeepStrictEqual(await current(task), beforeRefusal), 'Wrong approval ID must leave the original projection unchanged');
    await decide(task, pending.id, true, [409], Math.max(0, revision - 1));
    assert.ok(isDeepStrictEqual(await current(task), beforeRefusal), 'Stale approval revision must leave the original projection unchanged');
    await expected(base, `${endpoint(task)}/approve`, { ...auth, method: 'POST', body: { approved: true } }, [422]);
    assert.ok(isDeepStrictEqual(await current(task), beforeRefusal), 'Missing approval ID must leave the original projection unchanged');
    await expected(base, endpoint(task), { token: other }, [404]);
    const replay = await admit(id, !streaming);
    assert.equal(replay.uarTaskId, run.uarTaskId);
    assert.equal(admissions(), before + 1, 'Replay cannot create another provider attempt');
    await decide(task, pending.id, true);
    const done = await terminal(task, 'completed');
    assert.equal(done.uarRunId, run.uarRunId);
    assert.equal(effects(label), 1);
    const beforeDuplicate = await current(task);
    await decide(task, pending.id, true, [409]);
